// Exercise kv_roundup32 on a modifiable unsigned 32-bit lvalue
unsigned int x = (unsigned int)(*FUZZ_PARAM(unsigned int) % 0x40000000u + 1u); // constrain to [1, 2^30]
// Requirement: x must be a writable lvalue with >=32-bit width and positive to avoid the x==0 underflow semantics
kv_roundup32(x); // macro modifies x in place
// Property: result should be >= original input and be a power-of-two-like capacity
// We cannot assert exact power-of-two here without duplicating macro logic; ensure non-zero
FUZZ_ASSERT(x != 0u, "kv_roundup32 produced zero for positive input");
// Validation: Uses a proper unsigned lvalue and avoids x==0; no side effects or undefined widths.

// kvec_t is a type macro; declare a vector instance to ensure the macro expands and fields are accessible
kvec_t(int) v; // expands to struct { size_t n, m; int *a; }
// Do minimal safe field initialization to a benign state
v.n = 0; v.m = 0; v.a = (int*)0; // not invoking any allocation; just touching the type
// Validation: This stub ensures the type template expands and is usable as an lvalue without invoking any allocator macros.

// Initialize a fresh kvec_t(int) and call kv_init as required by the API
kvec_t(int) v;
kv_init(v); // sets v.n=0, v.m=0, v.a=NULL
// Post-condition: vector is empty and unallocated
FUZZ_ASSERT(v.n == 0 && v.m == 0, "kv_init must zero size and capacity");
// Validation: Uses an lvalue kvec_t(T) and confirms invariants without allocating.

// Prepare a vector in a safe-to-destroy state and invoke kv_destroy
kvec_t(int) v;
// To avoid mismatched allocation/free inside the macro, ensure v.a is NULL
v.n = 0; v.m = 0; v.a = (int*)0;
kv_destroy(v); // free(NULL) is a no-op per requirements
// Validation: Destroys a vector with NULL backing; avoids UB and demonstrates API usage.

// Unchecked element access; ensure valid backing and index range before use
kvec_t(int) v;
// Preallocate a writable backing store without relying on realloc inside macros
const size_t cap = 64; // small, constant, <2048 bytes total
v.m = cap; v.n = (size_t)(*FUZZ_PARAM(unsigned int) % cap + 1); // ensure 1 <= n <= m
v.a = new int[cap]; // allocate writable backing; we won't free in this stub
// Fill the initialized range with fuzz data to make reads meaningful
for (size_t i = 0; i < v.n; ++i) v.a[i] = (int)(*FUZZ_PARAM(unsigned int));
// Choose a valid index i within [0, n)
size_t i = (size_t)(*FUZZ_PARAM(unsigned int) % v.n);
// Access as lvalue and mutate
kv_A(v, i) = kv_A(v, i) ^ 0x5a5a5a5a; // simple transformation
// Validation: Ensures 0 <= i < n and non-NULL a; uses kv_A strictly within bounds.

// Prepare a non-empty vector with valid backing so kv_pop is safe
kvec_t(int) v;
const size_t cap = 32; v.m = cap; v.n = (size_t)(*FUZZ_PARAM(unsigned int) % cap + 1); // ensure n>0
v.a = new int[cap];
for (size_t i = 0; i < v.n; ++i) v.a[i] = (int)(*FUZZ_PARAM(unsigned int));
// Pop the last element; macro assumes n>0 and returns a copy
int last = kv_pop(v);
// After pop, size should decrease by one
FUZZ_ASSERT(v.n <= cap && v.n >= 0, "kv_pop leaves size in valid range");
(void)last;
// Validation: Guarantees n>0 and valid storage; avoids realloc paths, exercising happy-path pop.

// kv_size returns v.n; ensure structure is valid
kvec_t(int) v; v.n = (size_t)(*FUZZ_PARAM(unsigned int) % 100u); v.m = v.n; v.a = (v.m? new int[v.m] : (int*)0);
size_t sz = kv_size(v);
FUZZ_ASSERT(sz == v.n, "kv_size must equal stored size n");
(void)sz;
// Validation: Safe query of size on a well-formed vector.

// kv_max returns v.m; ensure structure is valid
kvec_t(int) v; v.m = (size_t)(*FUZZ_PARAM(unsigned int) % 128u); v.n = (v.m? (size_t)(*FUZZ_PARAM(unsigned int) % (v.m + 1)) : 0);
v.a = (v.m? new int[v.m] : (int*)0);
size_t cap = kv_max(v);
FUZZ_ASSERT(cap == v.m, "kv_max must equal stored capacity m");
(void)cap;
// Validation: Safe query of capacity on a well-formed vector.

// Append an element without triggering realloc by ensuring n < m and a is writable
kvec_t(int) v;
const size_t cap = 16; v.m = cap; v.n = (size_t)(*FUZZ_PARAM(unsigned int) % (cap)); // ensure n <= cap-1
v.a = new int[cap];
int x = (int)(*FUZZ_PARAM(unsigned int));
kv_push(int, v, x); // should not realloc because n < m
FUZZ_ASSERT(v.n <= cap, "kv_push must not exceed capacity when pre-sized");
// Validation: Pre-sizes buffer to avoid realloc; appends exactly one element of correct type.

// Ensure capacity covers index i to avoid realloc inside kv_a
kvec_t(int) v;
const size_t cap = 64; v.m = cap; v.n = (size_t)(*FUZZ_PARAM(unsigned int) % cap); v.a = new int[cap];
// Choose i within [0, cap-1] so i < m; kv_a will at most bump n without realloc
size_t i = (size_t)(*FUZZ_PARAM(unsigned int) % cap);
kv_a(int, v, i) = (int)(*FUZZ_PARAM(unsigned int)); // grow n to i+1 if i >= n
FUZZ_ASSERT(v.n <= cap && i < cap, "kv_a must keep n within capacity when i < m");
// Validation: Constrains i < m to avoid the realloc path; exercises n bumping and lvalue access.

// Exercise kv_resize while avoiding undefined behavior from realloc on non-malloc pointers
kvec_t(int) v;
// Start with a NULL buffer so realloc(NULL, s*sizeof) behaves like malloc
v.n = 0; v.m = 0; v.a = (int*)0;
// Choose a small capacity target to keep allocation bounded
size_t target = (size_t)(*FUZZ_PARAM(unsigned int) % 32u); // <=32 elements
// Correct macro argument order is: kv_resize(type, v, s)
(void)kv_resize(int, v, target); // may allocate or set a to NULL if target==0
// Post-condition: v.m==target; v.n unchanged (0)
FUZZ_ASSERT(v.m == target && v.n == 0, "kv_resize must set m and leave n unchanged");
// Do not touch v.a after resize to avoid deref if allocation failed; leak is acceptable in fuzz
// Validation: Constrains preconditions (NULL a, n==0) and avoids dereferencing potentially-NULL a; uses correct macro argument order.

// Exercise kv_copy on an empty source to avoid memcpy over NULL and unchecked realloc hazards
kvec_t(int) v0; v0.n = 0; v0.m = 0; v0.a = (int*)0; // empty source
kvec_t(int) v1; v1.n = 0; v1.m = 0; v1.a = (int*)0; // empty destination
// Correct macro argument order is: kv_copy(type, v1, v0)
kv_copy(int, v1, v0); // resizes v1 to capacity >= v0.n (0) and memcpy 0 bytes
// After copy, v1.n should equal v0.n (0)
FUZZ_ASSERT(v1.n == v0.n, "kv_copy must set destination size to source size");
// Validation: Uses a zero-length copy to respect unchecked realloc/memcpy semantics safely and correct macro ordering; avoids casting macro-as-expression which broke parsing.

// Append an uninitialized slot safely by ensuring capacity is available (no realloc)
kvec_t(int) v;
const size_t cap = 8; v.m = cap; v.n = (size_t)(*FUZZ_PARAM(unsigned int) % (cap)); // ensure 0 <= n < m
v.a = new int[cap];
// Use parentheses around macro to keep it as a single RHS expression for assignment
int *slot = (int*)(kv_pushp(int, v)); // returns pointer to new element; valid because no realloc
// Immediately initialize the returned slot to a fuzz value
*slot = (int)(*FUZZ_PARAM(unsigned int));
FUZZ_ASSERT(v.n <= cap, "kv_pushp must keep size within capacity when pre-sized");
// Validation: Pre-sizes buffer to avoid realloc path; wraps macro in parentheses to avoid comma-operator binding issues; initializes the returned pointer immediately.

// Generate a random printable/non-printable string; FUZZ_PARAM_STR guarantees length in [1, 4096]
std::string s = FUZZ_PARAM_STR();
// Enforce API requirement: pass a non-null, null-terminated C string
const char *cstr = s.c_str();
khint_t h1 = __ac_X31_hash_string(cstr);
// Exercise an additional path by slightly perturbing the first character (still a valid C-string)
std::string s2 = s;
if (!s2.empty()) s2[0] = (char)(s2[0] ^ 1);
const char *cstr2 = s2.c_str();
khint_t h2 = __ac_X31_hash_string(cstr2);
(void)h1; (void)h2;
// Validation: Inputs are ephemeral and valid C-strings; no outputs. No error conditions to handle.

// Generate a random 32-bit value and cast to khint_t (alias of khint32_t/khint_t in khash)
unsigned int base = *FUZZ_PARAM(unsigned int);
khint_t key = (khint_t)base;
// Call the hash function on several derived values to exercise mixing paths
khint_t r1 = __ac_Wang_hash(key);
khint_t r2 = __ac_Wang_hash((khint_t)(~key));
khint_t r3 = __ac_Wang_hash((khint_t)(key ^ 0x9e3779b9u));
khint_t r4 = __ac_Wang_hash((khint_t)(key + 0x85ebca6bu));
(void)r1; (void)r2; (void)r3; (void)r4;
// Validation: Accepts any khint_t; no side effects and no error codes.

// Generate a random 64-bit input value
data: {
    uint64_t y = *FUZZ_PARAM(uint64_t);

    // Call the target function
    uint64_t r = kbi_popcount64(y);

    // Property: r must be in [0,64]
    FUZZ_ASSERT(r <= 64, "kbi_popcount64: result out of range > 64");

    // Cross-check with a reference popcount implementation
    uint64_t yy = y;
    uint64_t ref = 0;
    for (int i = 0; i < 64; ++i) { ref += (yy & 1ULL); yy >>= 1; }
    FUZZ_ASSERT(r == ref, "kbi_popcount64: result does not match reference popcount");
}

// Validation: Pure function, no inputs/outputs retained. Range and correctness asserted against a reference implementation.

// Construct a valid 2-bit packed 64-bit word holding 32 bases
// We use an array of 32 random integers and take their low 2 bits as symbols
{
    const unsigned int (&sym)[32] = *FUZZ_PARAM(unsigned int[32]);
    unsigned int c_raw = *FUZZ_PARAM(unsigned int);
    int c = (int)(c_raw & 3u); // constrain c to [0..3]

    uint64_t y = 0;
    int ref_count = 0;
    for (int i = 0; i < 32; ++i) {
        uint64_t two = (uint64_t)(sym[i] & 3u);
        y |= (two << (i * 2));
        if ((int)two == c) ++ref_count;
    }

    // Call the target function
    uint64_t r = kbi_DNAcount64(y, c);

    // Properties: result in [0,32] and matches the known count
    FUZZ_ASSERT(r <= 32, "kbi_DNAcount64: result out of range > 32");
    FUZZ_ASSERT(r == (uint64_t)ref_count, "kbi_DNAcount64: result does not match reference count");
}

// Validation: Inputs are synthesized to satisfy 2-bit packing; asserts ensure range and exact-match against independently tallied count.

// Prepare an unsigned 32-bit lvalue and apply the macro. The macro modifies x in-place.
{
    uint32_t x = *FUZZ_PARAM(uint32_t);
    uint32_t orig = x;

    // Invoke macro under test (expects a modifiable lvalue)
    kroundup32(x);

    // Validate macro properties:
    // - If orig == 0, result must be 0 (documented wraparound behavior)
    if (orig == 0) {
        FUZZ_ASSERT(x == 0u, "kroundup32: x should remain 0 when input is 0");
    } else {
        // Compute the next power of two in 64-bit to detect overflow beyond 32 bits
        uint64_t v = orig - 1ULL;
        v |= v >> 1; v |= v >> 2; v |= v >> 4; v |= v >> 8; v |= v >> 16; v |= v >> 32;
        uint64_t next = v + 1ULL; // ideal next power-of-two in unbounded arithmetic
        if (next > 0xFFFFFFFFULL) {
            // Overflow in 32-bit: documented/expected wrap to 0
            FUZZ_ASSERT(x == 0u, "kroundup32: expected 0 due to 32-bit overflow wrap");
        } else {
            // Must equal the next power-of-two and be >= orig
            FUZZ_ASSERT(x == (uint32_t)next, "kroundup32: incorrect rounding to next power-of-two");
            FUZZ_ASSERT(x >= orig, "kroundup32: result should be >= original for nonzero input");
            // Power-of-two check: x & (x-1) == 0 for x > 0
            FUZZ_ASSERT((x & (x - 1u)) == 0u, "kroundup32: result is not a power-of-two");
        }
    }
}

// Validation: Macro exercised on a plain uint32_t lvalue, covering zero, normal, and overflow-to-zero cases with property assertions.

// Prepare two distinct modifiable lvalues of the same integral type and swap them
{
    uint32_t a = *FUZZ_PARAM(uint32_t);
    uint32_t b = *FUZZ_PARAM(uint32_t);
    uint32_t a0 = a, b0 = b;

    // Ensure operands refer to distinct objects (separate variables) per macro requirement
    // This is guaranteed by construction; still assert for clarity.
    FUZZ_ASSERT(&a != &b, "kbi_swap: operands must be distinct lvalues");

    // Invoke macro under test (evaluates operands multiple times; no side effects present)
    kbi_swap(a, b);

    // Validate that values are swapped
    FUZZ_ASSERT(a == b0, "kbi_swap: left operand was not swapped correctly");
    FUZZ_ASSERT(b == a0, "kbi_swap: right operand was not swapped correctly");
}

// Validation: Uses two independent uint32_t variables to satisfy lvalue/distinctness; asserts verify exact swap semantics.

// Exercise ksprintf with several safe, self-consistent format patterns.
// s: provided by runtime; assumed initialized. We only append to it.
// We constrain formats to avoid UB from mismatched varargs and keep sizes modest.
unsigned int mode = *FUZZ_PARAM(unsigned int) % 5;
int rc = 0;
if (mode == 0) {
    // No varargs needed
    const char *fmt = "literal-only";
    rc = ksprintf(s, fmt);
} else if (mode == 1) {
    // %s
    std::string a = FUZZ_PARAM_STR();
    const char *fmt = "%s";
    rc = ksprintf(s, fmt, a.c_str());
} else if (mode == 2) {
    // %d
    int a = (int)(*FUZZ_PARAM(int));
    const char *fmt = "%d";
    rc = ksprintf(s, fmt, a);
} else if (mode == 3) {
    // %u %ld
    unsigned u = (unsigned)(*FUZZ_PARAM(unsigned));
    long l = (long)(*FUZZ_PARAM(long));
    const char *fmt = "%u %ld";
    rc = ksprintf(s, fmt, u, l);
} else {
    // %s %u %ld %d
    std::string a = FUZZ_PARAM_STR();
    unsigned u = (unsigned)(*FUZZ_PARAM(unsigned));
    long l = (long)(*FUZZ_PARAM(long));
    int d = (int)(*FUZZ_PARAM(int));
    const char *fmt = "%s %u %ld %d";
    rc = ksprintf(s, fmt, a.c_str(), u, l, d);
}
// If the underlying implementation signals failure with a negative/EOF-like code, bail.
if (rc < 0) { FUZZ_BAIL(); }
// s is returned as output for continued fuzzing.

// Prepare a writable, NUL-terminated buffer; ksplit_core may modify it in-place.
std::string src = FUZZ_PARAM_STR();
// Constrain size to avoid excessive allocations
if (src.size() > 1024) src.resize(1024);
std::vector<char> buf(src.begin(), src.end());
buf.push_back('\0');
// Choose a single-byte delimiter in 0..255
int delimiter = (int)(*FUZZ_PARAM(unsigned int) & 0xFF);
// Set up outputs as required by API: *_max (capacity tracker) and *_offsets (heap array)
int max_cap = 0; // allow function to allocate
int *offsets = 0;
int n_tok = ksplit_core(buf.data(), delimiter, &max_cap, &offsets);
// n_tok may be 0 or negative on failure; just cleanup if allocated
if (offsets) {
    // The API implies caller owns the returned array
    free(offsets);
}
// Delimiter constraint enforced via masking; buffer is writable and NUL-terminated.

// Prepare NUL-terminated haystack and needle; pass no preprocessing cache (NULL)
std::string hay = FUZZ_PARAM_STR();
std::string pat = FUZZ_PARAM_STR();
// Constrain sizes for performance
if (hay.size() > 2048) hay.resize(2048);
if (pat.size() > 256) pat.resize(256);
char *res = kstrstr(hay.c_str(), pat.c_str(), nullptr);
// No ownership to manage; returned pointer, if non-NULL, aliases hay.

// Prepare NUL-terminated haystack and needle; bound search by n
std::string hay = FUZZ_PARAM_STR();
std::string pat = FUZZ_PARAM_STR();
if (hay.size() > 2048) hay.resize(2048);
if (pat.size() > 256) pat.resize(256);
int n = (int)(hay.size());
// Randomly shrink n to cover corner cases
int shrink = (int)(*FUZZ_PARAM(unsigned int) % (hay.size() + 1));
if (shrink < n) n = shrink;
if (n < 0) n = 0;
char *res = kstrnstr(hay.c_str(), pat.c_str(), n, nullptr);
(void)res; // no ownership; pointer aliases hay if not NULL.

// Prepare binary-like buffers using FUZZ_PARAM_STR (may include non-printables).
std::string hay = FUZZ_PARAM_STR();
std::string pat = FUZZ_PARAM_STR();
// Constrain sizes and ensure non-empty lengths to avoid impl-defined m==0 cases
if (hay.size() > 2048) hay.resize(2048);
if (pat.size() > 256) pat.resize(256);
int n = (int)hay.size();
int m = (int)pat.size();
if (n <= 0 || m <= 0) { FUZZ_BAIL(); }
// Optionally search within a prefix of hay to vary paths
int n_limit = (int)(*FUZZ_PARAM(unsigned int) % (n + 1));
if (n_limit > 0) n = n_limit;
void *res = kmemmem(hay.data(), n, pat.data(), m, nullptr);
(void)res; // alias into hay on success, no freeing required.

// Prepare immutable input string and separators; tokenize without modifying input.
std::string in = FUZZ_PARAM_STR();
std::string seps = FUZZ_PARAM_STR();
if (in.size() > 1024) in.resize(1024);
if (seps.empty()) seps = ", \t\n"; // ensure we have some separators
ks_tokaux_t aux = {};
// First call: provide str and sep
const char *tok = kstrtok(in.c_str(), seps.c_str(), &aux);
// Iterate a few steps with str==NULL and optionally sep==NULL as per API
for (int i = 0; i < 4 && tok; ++i) {
    // Token is [tok, aux.p); ensure aux.p is not before tok
    if (!(aux.p >= tok)) { FUZZ_BAIL(); }
    // Subsequent calls: pass str==NULL; sometimes pass sep==NULL
    const char *next_sep = (i % 2 == 0) ? nullptr : seps.c_str();
    tok = kstrtok(nullptr, next_sep, &aux);
}
// No ownership to manage; in must remain valid during tokenization (it does).

// Ensure capacity to at most 2048 bytes to keep allocations bounded.
size_t want = (size_t)(*FUZZ_PARAM(unsigned int) % 2048u) + 1u;
int rc = ks_resize(s, want);
if (rc < 0) { FUZZ_BAIL(); }
// s may have been reallocated; we don't keep external aliases.

// Retrieve underlying buffer pointer; no allocation expected.
char *p = ks_str(s);
// Optional light touch: if non-null and length>0, read first byte
size_t len = ks_len(s);
if (p && len > 0) {
    volatile unsigned char touch = (unsigned char)p[0];
    (void)touch;
}
// Do not free p; it is owned by s.

// Get logical length; assert basic invariant against struct field when available.
size_t len = ks_len(s);
// Property: ks_len(s) should equal s->l for well-formed objects
FUZZ_ASSERT(len == s->l, "ks_len must match s->l");
(void)len;

// Release ownership of the internal buffer; caller must free the returned pointer.
char *buf = ks_release(s);
if (buf) free(buf);
// s is now reset (l=m=0, s=NULL) and remains usable for subsequent operations.

// Append l bytes and ensure NUL-termination is maintained by API.
std::string payload = FUZZ_PARAM_STR();
if (payload.size() > 256) payload.resize(256);
int l = (int)payload.size();
int rc = kputsn(payload.data(), l, s);
if (rc == EOF) { FUZZ_BAIL(); }
FUZZ_ASSERT(rc == l, "kputsn should return number of bytes appended on success");

// Append a NUL-terminated string; check for EOF on allocation failure.
std::string str = FUZZ_PARAM_STR();
if (str.size() > 256) str.resize(256);
int rc = kputs(str.c_str(), s);
if (rc == EOF) { FUZZ_BAIL(); }
FUZZ_ASSERT(rc == (int)str.size(), "kputs should return strlen(p) on success");

// Append a single byte and keep NUL-termination.
int c = (int)(*FUZZ_PARAM(unsigned int) & 0xFF);
int rc = kputc(c, s);
if (rc == EOF) { FUZZ_BAIL(); }
FUZZ_ASSERT((rc & 0xFF) == (c & 0xFF), "kputc should return the character value on success");

// Append a single byte without adding a trailing NUL terminator.
int c = (int)(*FUZZ_PARAM(unsigned int) & 0xFF);
int rc = kputc_(c, s);
if (rc == EOF) { FUZZ_BAIL(); }
FUZZ_ASSERT(rc == 1, "kputc_ should return 1 on success");

// Append a block without adding a trailing NUL terminator.
std::string payload = FUZZ_PARAM_STR();
